			"id": "l-6d7667eaaee9",
			"factId": "mindmap",
			"title": "Các khái niệm đứng cạnh nhau thế nào",
			"courseId": "c-f3c8d7aa3721",
			"moduleId": "m-c15cbe7e9aa4",
			"sessionId": "s-3b11cdbb8daf",
