			"factId": "sql-case",
			"title": "CASE, hàm và câu hỏi kinh doanh trong SQL",
			"courseId": "c-3365bb99f989",
			"moduleId": "m-b87a9cee8b9d",
			"sessionId": "s-6e0d562298cf",
