			"title": "JOIN và phép tập hợp",
			"courseId": "c-cca6e1fa1c5f",
			"moduleId": "m-7afb45fe39a6",
			"sessionId": "s-9988f1da2145",
			"sessionTitle": "S4 Joins and Set Operations",
